// SPDX-License-Identifier: GPL-2.0-only
/*
 * Samsung ISOCELL HM2 (S5KHM2) 108 MP image sensor driver
 *
 * The sensor is connected over a 3-trio MIPI C-PHY link. Register settings
 * are taken from the vendor camera module configuration of the Xiaomi
 * Mi 11T Pro (vili) wide camera and use the 3x3 binned modes.
 */

#include <linux/clk.h>
#include <linux/delay.h>
#include <linux/gpio/consumer.h>
#include <linux/i2c.h>
#include <linux/module.h>
#include <linux/pm_runtime.h>
#include <linux/regulator/consumer.h>
#include <linux/units.h>

#include <media/v4l2-cci.h>
#include <media/v4l2-ctrls.h>
#include <media/v4l2-device.h>
#include <media/v4l2-event.h>
#include <media/v4l2-fwnode.h>

#define S5KHM2_REG_CHIP_ID		CCI_REG16(0x0000)
#define S5KHM2_CHIP_ID			0x1ad2
#define S5KHM2_REG_REVISION		CCI_REG8(0x0002)

#define S5KHM2_REG_MODE_SELECT		CCI_REG8(0x0100)
#define S5KHM2_MODE_STANDBY		0x00
#define S5KHM2_MODE_STREAMING		0x01
#define S5KHM2_REG_ORIENTATION		CCI_REG8(0x0101)
#define S5KHM2_REG_GROUP_HOLD		CCI_REG8(0x0104)

#define S5KHM2_REG_EXPOSURE		CCI_REG16(0x0202)
#define S5KHM2_EXPOSURE_MIN		6
#define S5KHM2_EXPOSURE_STEP		1
#define S5KHM2_EXPOSURE_MARGIN		10

#define S5KHM2_REG_ANALOG_GAIN		CCI_REG16(0x0204)
#define S5KHM2_ANA_GAIN_MIN		0x20
#define S5KHM2_ANA_GAIN_MAX		0x500
#define S5KHM2_ANA_GAIN_STEP		1
#define S5KHM2_ANA_GAIN_DEFAULT		0x20

#define S5KHM2_REG_DGAIN_GR		CCI_REG16(0x020e)
#define S5KHM2_REG_DGAIN_R		CCI_REG16(0x0210)
#define S5KHM2_REG_DGAIN_B		CCI_REG16(0x0212)
#define S5KHM2_REG_DGAIN_GB		CCI_REG16(0x0214)
#define S5KHM2_DGTL_GAIN_MIN		0x100
#define S5KHM2_DGTL_GAIN_MAX		0xfff
#define S5KHM2_DGTL_GAIN_STEP		1
#define S5KHM2_DGTL_GAIN_DEFAULT	0x100

#define S5KHM2_REG_FLL			CCI_REG16(0x0340)
#define S5KHM2_FLL_MAX			0xffff

#define S5KHM2_REG_TEST_PATTERN		CCI_REG16(0x0600)

/* 3x3 binned output area, in native sensor pixels */
#define S5KHM2_NATIVE_WIDTH		12000U
#define S5KHM2_NATIVE_HEIGHT		9000U

#define S5KHM2_MCLK_FREQ		19200000

/*
 * Output PLL: 19.2 MHz / 3 * 281 / 2 = 899.2 MHz symbol rate per trio. Each
 * C-PHY symbol carries 16/7 bits, so three trios move 6.166 Gbps, which is
 * 616.6 Mpixel/s of RAW10.
 */
#define S5KHM2_LINK_FREQ		899200000ULL
#define S5KHM2_NUM_TRIOS		3
#define S5KHM2_BPP			10
#define S5KHM2_PIXEL_RATE \
	((u64)S5KHM2_LINK_FREQ * S5KHM2_NUM_TRIOS * 16 / 7 / S5KHM2_BPP)

/* Video timing pixel clock: 19.2 MHz / 3 * 250 */
#define S5KHM2_VT_PIX_CLK		1600000000ULL

struct s5khm2_reg {
	u16 addr;
	u16 val;
};

struct s5khm2_reg_list {
	const struct s5khm2_reg *regs;
	unsigned int num_regs;
};

struct s5khm2_mode {
	u32 width;
	u32 height;
	/* Line length in video timing pixel clocks */
	u32 llp;
	/* Default frame length in lines */
	u32 fll_def;
	struct v4l2_rect crop;
	struct s5khm2_reg_list reg_list;
};

static const char * const s5khm2_supply_names[] = {
	"vdig",	/* Digital core (1.05 V) */
	"vana",	/* Analog (2.8 V) */
	"vio",	/* I/O (1.8 V) */
};

static const s64 s5khm2_link_freqs[] = {
	S5KHM2_LINK_FREQ,
};

static const char * const s5khm2_test_pattern_menu[] = {
	"Disabled",
	"Solid Colour",
	"Eight Vertical Colour Bars",
	"Colour Bars With Fade to Grey",
	"Pseudorandom Sequence (PN9)",
};

